          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (max-width: 880px) {
        .header-inner {
          grid-template-columns: auto auto 1fr;
        }

        .nav-toggle {
          display: inline-flex;
          align-items: center;
          justify-content: center;
