            email.focus();
            return;
          }

          message.dataset.state = "success";
          message.textContent = "You are on the list. Watch your inbox for the next member drop.";
          form.reset();
        });
      }

      document.querySelector("#app").innerHTML = App();
      bindNavigation();
      bindCart();
      bindNewsletter();
